import { AbstractInputField } from '../shared/abstract-input-field';
import { createElement, dynamicAttr, elementIsDisabled, replace, updateDynamicAttribute, updateDynamicAttributeOnChildren } from '../shared/dom-manipulation';
import { getRequiredOnlyValidators } from '../shared/validation-engine/validate-engine';
import './neon-radio-field.scss';
export class NeonRadioField extends AbstractInputField {
    static get observedAttributes() {
        return super.observedAttributes.concat([
            'data-group-name',
            'data-control-layout'
        ]);
    }
    set options(value) {
        if (value instanceof Array) {
            value = value.filter((option) => {
                const isValidValue = option.value != null && option.value.length > 0;
                if (!isValidValue) {
                    console.error('An array option was removed because the value = \'\'');
                }
                return isValidValue;
            });
        }
        //We need to check to see if the new array of options has the same value as
        //What's currently here.  If everything is the same, then there will be no reason to redraw the radios.
        let isDifferent = false;
        if (this.options != null && value != null && this.options.length === value.length) {
            for (let i = 0; i < this.options.length; i++) {
                const newRadioOption = value[i];
                const oldRadioOption = this.options[i];
                if (oldRadioOption.id !== newRadioOption.id ||
                    oldRadioOption.labelText !== newRadioOption.labelText ||
                    oldRadioOption.value !== newRadioOption.value ||
                    oldRadioOption.disabled !== newRadioOption.disabled ||
                    oldRadioOption.helperText !== newRadioOption.helperText) {
                    isDifferent = true;
                    break; //Once we know it's different, we don't have to keep checking
                }
            }
        }
        else {
            isDifferent = true;
        }
        this._options = value;
        if (isDifferent) {
            this.redrawRadios();
            if (this.runValidationOnceOptionsSet) {
                this.validateWidget();
                this.runValidationOnceOptionsSet = false;
            }
        }
    }
    get options() {
        return this._options;
    }
    constructor() {
        super();
        this.widgetTag = 'neon-radio-field';
        this.isUsesLabel = false;
        this.isUsesLegend = true; // This is set to true because the legend is used as the label for the field.
        // Prevents race condition to prevent the validation appearing
        // after modelValue getting set before the options are set.
        this.runValidationOnceOptionsSet = false;
    }
    generateValidationRules() {
        this.validators = getRequiredOnlyValidators(this.getAttribute('data-is-required') === 'true');
        this.addCustomValidateToValidators();
    }
    renderInputElement() {
        return createElement('div');
    }
    validateModelValueType(modelValue) {
        if (typeof modelValue === 'string' && modelValue.length > 0) {
            return modelValue;
        }
        return undefined;
    }
    setModelValue(modelValue, skip) {
        if ((this.modelValue == null) && (modelValue == null)) {
            return false;
        }
        if (modelValue !== this._modelValue) {
            this._modelValue = modelValue;
            if (skip !== true) {
                this.setValue(modelValue, true);
            }
            return true;
        }
        return false;
    }
    setValue(value, skip) {
        if (value == null) {
            value = '';
        }
        const radioInputElements = this.querySelectorAll('neon-2_20_1-radio-single');
        if (radioInputElements != null) {
            for (const radioSingle of Array.from(radioInputElements)) {
                const newValue = radioSingle.getAttribute('data-option-value') === value;
                radioSingle.value = newValue;
            }
        }
        if (skip !== true) {
            this.setModelValue(value, true);
        }
    }
    get value() {
        for (const radioSingle of Array.from(this.querySelectorAll('neon-2_20_1-radio-single'))) {
            if (radioSingle.value === true) {
                return radioSingle.getAttribute('data-option-value');
            }
        }
    }
    get modelValue() {
        return this._modelValue;
    }
    set modelValue(value) {
        value = this.validateModelValueType(value);
        const modelValueChanged = this.setModelValue(value);
        if (modelValueChanged) {
            if (this.options != null) {
                this.validateWidget();
                if (this.isValid) {
                    this.setError('');
                }
            }
            else {
                //Defer validation until the options have been set.
                this.runValidationOnceOptionsSet = true;
            }
        }
        this.setReadonlyText();
    }
    render() {
        if (this.getAttribute('data-is-read-only') === 'true') {
            return createElement('div', {
                attrs: {
                    class: 'neon-checkbox-field-read-only-fieldset'
                }
            }, ...this.renderFieldLabels(), this.renderRadios());
        }
        return createElement('fieldset', {}, ...this.renderFieldLabels(), this.renderRadios(), this.errorElement, //Note: The order here is expected in redrawRadios()
        this.successElement);
    }
    renderRadios() {
        //Make sure we start with an array of some kind, even if empty.
        const options = this.options || [];
        return createElement('div', {
            attrs: {
                class: dynamicAttr(() => {
                    let inputsContainerClasses = 'neon-radio-field-inputs neon-input-field-first';
                    if (this.getAttribute('data-control-layout') === 'row') {
                        inputsContainerClasses += ' neon-radio-field-row-layout';
                    }
                    return inputsContainerClasses;
                })
            }
        }, ...options.map((option) => {
            return createElement('neon-2_20_1-radio-single', {
                attrs: {
                    id: option.id,
                    'data-label-text': option.labelText,
                    name: dynamicAttr(() => { return this.getAttribute('data-group-name') || this.getAttribute('id') + '-group-name'; }),
                    'data-option-value': option.value,
                    disabled: dynamicAttr(() => {
                        if (elementIsDisabled(this)) {
                            return 'true';
                        }
                        else {
                            return (option.disabled != null ? String(option.disabled) : undefined);
                        }
                    }),
                    'data-helper-text': option.helperText,
                    'data-size': dynamicAttr(() => { return this.getAttribute('data-size'); }),
                    'data-is-read-only': this.getAttribute('data-is-read-only')
                },
                properties: {
                    value: this.modelValue === option.value
                },
                listeners: {
                    change: (event) => {
                        this.errorPresentWhenBlurOccurred = true;
                        this.inputChange();
                    },
                    'blur': (event) => { return this.focusLost(event); }
                }
            });
        }));
    }
    redrawRadios() {
        replace(this.renderRadios(), this.querySelector('.neon-radio-field-inputs'));
    }
    attributeChanged(attribute, oldValue, newValue) {
        // attributeChanged is called when attributes listed in "static get observedAttributes()" are changed.
        super.attributeChanged(attribute, oldValue, newValue);
        switch (attribute) {
            case 'id':
                updateDynamicAttribute(this, 'name');
                break;
            case 'data-group-name':
                updateDynamicAttribute(this, 'name');
                break;
            case 'disabled':
                updateDynamicAttribute(this, 'disabled');
                break;
            case 'data-control-layout':
                updateDynamicAttribute(this, 'class');
                break;
            case 'data-size':
                updateDynamicAttributeOnChildren(this, 'data-size');
                break;
            case 'data-is-read-only':
                this.isUsesLegend = newValue !== 'true';
                this.redraw();
                break;
        }
    }
}
